                    <button onClick={handleReset} style={{ marginTop: '1rem', background: 'transparent', border: '1px solid rgba(255,255,255,0.15)', color: '#fff', padding: '0.5rem 1.25rem', borderRadius: '8px', cursor: 'pointer', fontSize: '13px' }}>
                        Reset Filters
                    </button>
                </div>
