                    <motion.div
                        style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: '12px' }}
                    >
                        {paginated.map(v => (
                            <VesselCard
                                key={v.id}
                                vessel={v}
                                isSubscribed={subscribedIds.has(v.id)}
                                isToggling={togglingId === v.id}
                                isAuthenticated={isAuthenticated}
                                onToggle={handleToggleSubscription}
                            />
                        ))}
                    </motion.div>

                    {/* Pagination */}
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', paddingTop: '8px', flexWrap: 'wrap', gap: '0.75rem' }}>
                        <span style={{ color: 'var(--text-2)', fontSize: '13px' }}>
                            {(page - 1) * PAGE_SIZE + 1}ΓÇô{Math.min(page * PAGE_SIZE, filtered.length)} of {filtered.length} vessels
                        </span>
                        {totalPages > 1 && (
                            <div style={{ display: 'flex', gap: '6px' }}>
                                <button style={{ background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', color: 'var(--text-1)', padding: '0.4rem 0.85rem', borderRadius: '8px', cursor: page === 1 ? 'not-allowed' : 'pointer', opacity: page === 1 ? 0.5 : 1, fontSize: '13px' }} onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page === 1}>ΓåÉ Prev</button>
                                {Array.from({ length: Math.min(7, totalPages) }, (_, i) => {
                                    let p = page <= 4 ? i + 1 : page >= totalPages - 3 ? totalPages - 6 + i : page - 3 + i;
                                    if (p < 1) p = 1; if (p > totalPages) p = totalPages;
                                    return (
                                        <button key={p} onClick={() => setPage(p)}
                                            style={{ background: page === p ? 'rgba(56,189,248,0.15)' : 'rgba(255,255,255,0.04)', border: page === p ? '1px solid rgba(56,189,248,0.5)' : '1px solid rgba(255,255,255,0.08)', color: page === p ? '#38bdf8' : 'var(--text-1)', padding: '0.4rem 0.7rem', borderRadius: '8px', cursor: 'pointer', fontWeight: page === p ? 700 : 400, fontSize: '13px' }}
                                        >{p}</button>
                                    )
                                })}
                                <button style={{ background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', color: 'var(--text-1)', padding: '0.4rem 0.85rem', borderRadius: '8px', cursor: page === totalPages ? 'not-allowed' : 'pointer', opacity: page === totalPages ? 0.5 : 1, fontSize: '13px' }} onClick={() => setPage(p => Math.min(totalPages, p + 1))} disabled={page === totalPages}>Next ΓåÆ</button>
                            </div>
                        )}
                    </div>
                </>
            )}
        </div>
    )
}

